import React, { forwardRef, PropsWithChildren, ReactElement } from 'react';

import { renderMenuActionChildren } from './functions/render-menu-action-children.js';
import { Menu } from '../../../../navigation/menu/Menu.js';
import { TooltipActionTemplate } from '../tooltip/shared/hooks/useTooltipSeriesActions.js';

export interface ChartActionsMenuProps {
  /** Controlled open or closed state */
  isOpen: boolean;
  /** Series actions to display **/
  actions?: TooltipActionTemplate;
  /** Handler for the action click */
  onActionClick?: (e: React.MouseEvent) => void;
}

/**
 * ChartActionsMenu component.
 */
export const ChartActionsMenu = forwardRef<
  HTMLDivElement,
  PropsWithChildren<ChartActionsMenuProps>
>((props: PropsWithChildren<ChartActionsMenuProps>, forwardedRef) => {
  const { children, isOpen, actions, onActionClick } = props;

  return (
    <div onClick={onActionClick}>
      <Menu open={isOpen} modal={false}>
        <Menu.Trigger>{children}</Menu.Trigger>
        {isOpen && (
          <Menu.Content ref={forwardedRef} side="right">
            {actions &&
              React.Children.map(
                actions()?.props.children,
                (child: ReactElement) => renderMenuActionChildren(child),
              )}
          </Menu.Content>
        )}
      </Menu>
    </div>
  );
});

ChartActionsMenu['displayName'] = 'ChartActionsMenu';
